//! Application commands: about (version, contributors), the command and query lists.

use serde_json::{Value, json};

use crate::command::{CommandFuture, CommandSpec, always};
use crate::session::Session;

/// Commit stats, generated by `cargo xtask contributors` (compiled in).
const CONTRIBUTORS_JSON: &str = include_str!("../../../../contributors/contributors.json");
/// Names contributors chose for themselves (compiled in).
const PEOPLE_TOML: &str = include_str!("../../../../contributors/people.toml");

/// Most contributors listed in About.
const MAX_CONTRIBUTORS: usize = 500;

pub(crate) fn commands() -> Vec<CommandSpec> {
    vec![
        CommandSpec {
            id: "app.about",
            label: "About Quorum",
            menu: Some("Quorum/About Quorum"),
            shortcut: None,
            params_doc: "{} -> {name, version, contributors: [{name, username?, commits}]}",
            destructive: false,
            enabled: always,
            run: about,
        },
        CommandSpec {
            id: "app.commands",
            label: "List Commands",
            menu: None,
            shortcut: None,
            params_doc: "{}",
            destructive: false,
            enabled: always,
            run: list,
        },
    ]
}

pub(crate) fn queries() -> Vec<CommandSpec> {
    vec![
        CommandSpec {
            id: "app.commands",
            label: "Commands",
            menu: None,
            shortcut: None,
            params_doc: "{}",
            destructive: false,
            enabled: always,
            run: list,
        },
        CommandSpec {
            id: "app.queries",
            label: "Queries",
            menu: None,
            shortcut: None,
            params_doc: "{} -> [{id, label, params_doc}]",
            destructive: false,
            enabled: always,
            run: list_queries,
        },
        CommandSpec {
            id: "app.about",
            label: "About Quorum",
            menu: None,
            shortcut: None,
            params_doc: "{} -> {name, version, contributors}",
            destructive: false,
            enabled: always,
            run: about,
        },
    ]
}

fn about(_s: &Session, _p: Value) -> CommandFuture<'_> {
    Box::pin(async move {
        Ok(json!({
            "name": "Quorum",
            "version": env!("CARGO_PKG_VERSION"),
            "licence": "MIT OR Apache-2.0",
            "contributors": contributors(CONTRIBUTORS_JSON, PEOPLE_TOML),
        }))
    })
}

fn list(s: &Session, _p: Value) -> CommandFuture<'_> {
    Box::pin(async move { Ok(serde_json::to_value(s.commands())?) })
}

fn list_queries(s: &Session, _p: Value) -> CommandFuture<'_> {
    Box::pin(async move {
        Ok(Value::Array(
            s.queries().iter().map(|q| json!({ "id": q.id, "label": q.label, "params_doc": q.params_doc })).collect(),
        ))
    })
}

/// Contributors for About: commit stats merged with the names people chose (pure, tested).
///
/// An entry's `username` (or `login`) selects its `[people.<username>]` table; `display_name`
/// wins over `real_name`, which wins over the generated name. Malformed input yields fewer rows.
pub(crate) fn contributors(stats_json: &str, people_toml: &str) -> Vec<Value> {
    let stats: Value = serde_json::from_str(stats_json).unwrap_or(Value::Null);
    let people = parse_people(people_toml);
    let list = stats.get("contributors").and_then(Value::as_array).cloned().unwrap_or_default();
    list.iter()
        .take(MAX_CONTRIBUTORS)
        .filter_map(|c| {
            let text = |k: &str| c.get(k).and_then(Value::as_str).map(str::to_owned);
            let username = text("username").or_else(|| text("login"));
            let chosen = username.as_ref().and_then(|u| people.iter().find(|(name, _)| name == u)).map(|(_, f)| f);
            let field = |k: &str| chosen.and_then(|f| f.iter().find(|(key, _)| key == k)).map(|(_, v)| v.clone());
            let name =
                field("display_name").or_else(|| field("real_name")).or_else(|| text("name")).or(username.clone())?;
            let commits = c.get("commits").and_then(Value::as_u64).unwrap_or(0);
            Some(json!({ "name": name, "username": username, "commits": commits }))
        })
        .collect()
}

type Fields = Vec<(String, String)>;

/// Reads the `[people.<username>]` tables of `people.toml`: string keys only, no nesting.
fn parse_people(text: &str) -> Vec<(String, Fields)> {
    let mut out: Vec<(String, Fields)> = Vec::new();
    for line in text.lines().take(10_000) {
        let line = line.trim();
        if line.starts_with('#') || line.is_empty() {
            continue;
        }
        if let Some(header) = line.strip_prefix('[').and_then(|l| l.strip_suffix(']')) {
            if let Some(user) = header.trim().strip_prefix("people.") {
                out.push((user.trim().trim_matches('"').to_owned(), Vec::new()));
            }
            continue;
        }
        let Some((key, value)) = line.split_once('=') else { continue };
        let value = value.split(" #").next().unwrap_or_default().trim();
        let Some(value) = value.strip_prefix('"').and_then(|v| v.strip_suffix('"')) else { continue };
        if let Some((_, fields)) = out.last_mut() {
            let value: String = value.chars().filter(|c| !c.is_control()).take(100).collect();
            fields.push((key.trim().to_owned(), value));
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn contributors_merge_chosen_names() {
        let stats = r#"{"contributors":[{"name":"gen one","username":"one","commits":3},{"name":"two","commits":1},{"commits":2}]}"#;
        let people = "# comment\n[people]\n[people.one]\nreal_name = \"Real One\"\ndisplay_name = \"One\" # hi\n";
        let list = contributors(stats, people);
        assert_eq!(list.len(), 2);
        assert_eq!(list.first().and_then(|c| c.get("name")).and_then(Value::as_str), Some("One"));
        assert_eq!(list.get(1).and_then(|c| c.get("name")).and_then(Value::as_str), Some("two"));
    }

    #[test]
    fn contributors_tolerate_garbage() {
        assert!(contributors("not json", "[[[").is_empty());
        assert!(contributors(r#"{"contributors": 5}"#, "").is_empty());
        let _ = contributors(CONTRIBUTORS_JSON, PEOPLE_TOML);
    }
}
